{{-- scouting-area.tsx Pager. Variabili: $total, $size, $page, $setter (metodo Livewire) e $label (nome accessibile della navigazione). --}}
@php($lastPage = max(1, (int) ceil($total / $size)))
<div class="census-pager" role="navigation" aria-label="{{ $label }}"><span>{{ $total }} risultati · pagina {{ $page }} di {{ $lastPage }}</span><div class="crm-actions"><button type="button" class="crm-btn secondary" wire:click="{{ $setter }}({{ $page - 1 }})" @disabled($page <= 1)>Precedente</button><button type="button" class="crm-btn secondary" wire:click="{{ $setter }}({{ $page + 1 }})" @disabled($page >= $lastPage)>Successiva</button></div></div>
